import Container from '@mui/material/Container'
import Stack from '@mui/material/Stack'

export default function GamesHeader() {
  return (
    <Stack direction="row" spacing={2} sx={{justifyContent: "space-between", alignItems: "flex-start", width: '100%'}}>
        <img src="../images/ducks-left.svg" style={{width: '15%', height: '15vh'}}></img>
        <h1 style={{color: 'white', fontWeight: 'bolder', textAlign: 'center'}}>Games</h1>
        <img src="../images/single-duck.svg" style={{width: '15%', height: '15vh'}}></img>
    </Stack>
  );
}
